INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('videocart-4-spitfire', 41218, '1977-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co705n.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ksbf5w8fxbek4bzcfp7v.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Videocart-4: Spitfire', 'Videocart-4: Spitfire is a 1 on 1 aerial dogfighting Shooter game released by Fairchild Semiconductor for the Fairchild Channel F in 1977. In addition to a 2 player mode the game allowed for 1 player to combat the CPU, which for the time was unique for a home console thanks to the Channel F being the first home console with a CPU.
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 41218 AND ge.slug = 'shooter' ON CONFLICT DO NOTHING;
INSERT INTO game_companies (game_id, company_id, role, is_primary) SELECT g.id, c.id, 'developer', false FROM games g, companies c WHERE g.igdb_id = 41218 AND c.slug = 'fairchild-semiconductor' ON CONFLICT DO NOTHING;
INSERT INTO game_platforms (game_id, platform_id) SELECT g.id, p.id FROM games g, platforms p WHERE g.igdb_id = 41218 AND p.igdb_id = 127 ON CONFLICT DO NOTHING;
