INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('depthcharge', 18609, '1977-09-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/ym8z4bl1bncupbz6gvmw.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scplpb.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Depthcharge', 'Depthcharge is a single-player arcade game released in 1977 by Gremlin Industries for the Sega VIC Dual system board. The game presents the player with a cut-away view of a section of ocean, on the surface of which is a destroyer with submarines passing beneath it. The player drops depth charges (up to six at a time) to destroy the submarines and moves the ship back and forth in order to avoid the submarines'' mines. Up to four submarines may be present at any given time, each of which bears a score for destroying it that increases with its depth.
