INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Speed Race', 'Super Speed Race GP V (released as "Super Speed Race" in North America, and as "Speed Race CL-5" in Europe) is an edition in Speed Race series. The primary gameplay stays identical to earlier games in the series. The player races in a top-down view and must pass other cars to score points. Compared to its predecessor Super Speed Race there are some new elements like the cars'' headlights emitting light in tunnels and water slicks on the track. Also new are bridges where the player must choose between two paths and not crash against the divider.' FROM games WHERE igdb_id = 40461 ON CONFLICT (game_id, language_code) DO NOTHING;
