INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Circus', 'Circus was one of the first games produced by Exidy that used a CPU (6502) to control the game logic instead of hand-crafted hard-coded logic circuits. It ran on a black & white monitor with a color overlay that gave each row of balloons at the top of the screen a different color. It was designed and programmed by Edward Valeau and Howell Ivey of Exidy in 1977.
