INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('destroyer', 18611, '1977-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cxo411gs0eblirpeduth.jpg', NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Destroyer', 'Destroyer is a single player 1977 arcade game developed and published by Atari, Inc. The playfield displays your ship moving across the surface (displayed as a wavy line) and submarines moving across the screen. The target depth is set using a dial control (displayed as a dashed line). Depth charges are dropped by pushing the dial control. The speed of your ship is controlled using a speed lever control. Charges that miss make a low boom. Charges that hit make a louder boom and trigger an explosion sequence. Points are awarded for successful hits. The game is timed, so the goal is to sink or destroy as many submarines as possible before the time expires.' FROM games WHERE igdb_id = 18611 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 18611 AND ge.slug = 'arcade' ON CONFLICT DO NOTHING;
