INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('blackjack', 41530, '1977-09-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8wey.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scu2wt.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Blackjack', 'Atari''s Blackjack employs a variant of blackjack rules that is so extremely unfavorable to the player, that it would almost certainly never be seen in a real casino because no one would play with them. Splitting pairs is not allowed, and even more substantially, draws are won by the dealer (your bet is not returned to you if you and the dealer get the same card total and neither busts). This represents over a 10% house advantage. The player uses the paddle controller to enter a bet of up to 25 chips from an initial pot of 200. An up card is then presented, and the player decides whether to "hit" (accept another card) or stand. The player breaks the bank by obtaining a score of 1,000 chips, or is "busted" upon losing everything.
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 41530 AND ge.slug = 'card-and-board-game' ON CONFLICT DO NOTHING;
