INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Color TV-Game 15', 'Color TV-Game 15 is the sequel to Color TV-Game 6. This game features fifteen different variations of Light Tennis, whereas the original only has six. Like Color TV-Game 6, Color TV-Game 15 was very successful, selling over a million copies in Japan. The controllers were now separate from the console, while in the original the players were required to turn the knobs on the actual console.' FROM games WHERE igdb_id = 220549 ON CONFLICT (game_id, language_code) DO NOTHING;
