INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hustle', 'Hustle is a 1977 game by Gremlin on Blockade hardware that is effectively Snake except that the normal pellets are replaced with larger pieces containing various point values that you get if you touch the piece before it disappears. Multiple pieces may also appear at once. You have one life; the game ends either when you hit yourself/a boundary or run out of time (the operator is presumably able to change how much time you can play for).' FROM games WHERE igdb_id = 40054 ON CONFLICT (game_id, language_code) DO NOTHING;
