INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Score', 'Developed by Exidy, Score is another extension of the Destruction Derby concept with the cars replaced by bar patrons. Set in a singles bar, the object of the game is to “score” with as many members of the opposite sex as possible. When the onscreen Lothario makes contact with the object of his (or her) affections, a heart appears on screen. A cocktail version of the game came in a heart-shaped cabinet.' FROM games WHERE igdb_id = 171268 ON CONFLICT (game_id, language_code) DO NOTHING;
