INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Blockbuster', 'Blockbuster was released by Elcon Industries in 1977. Blockbuster is an arcade cabinet featuring five different games that can be played: Magic Squares, Tennis (Pong variant), Soccer (Pong variant), Gravity Ball (Pong variant with gravity) and Blockbuster (Breakout variant). Depending on the game up to four players can play. The game is available in four different cabinet styles (round cocktail, octagonal cocktail, rectangular cocktail and cabinet).' FROM games WHERE igdb_id = 327740 ON CONFLICT (game_id, language_code) DO NOTHING;
