INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'System 10', 'System 10 is a home video game machine released by Epoch in 1978. Developed jointly with NEC and equipped with NEC''s µPD770C chip. It has 10 built-in games, and you can play ponclone games such as tennis, ping-pong, and soccer, as well as shooting games using a gun-shaped controller. It is an early home-use game machine classified as the first generation. Later, a cheaper version of "System 10 M2" was also released. There is also an OEM model called "Toshiba Video Game TVG-610" which uses the same IC and has the same content developed by Epoch and released by Toshiba.' FROM games WHERE igdb_id = 251171 ON CONFLICT (game_id, language_code) DO NOTHING;
