INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Robot Bowl', 'Robot Bowl was a black & white bowling alley game designed and programmed by Edward Valeau and Howell Ivey of Exidy. The game featured one or two robot bowlers playing with the standard bowling rules. To control the outcome, the game had five buttons: left, right, shoot, hook left, and hook right. "Hooking" the ball was the key to getting a good score, as you could only hook the ball after it had been thrown. This made it easy to pick up a spare, but the game made up for it by making splits very common.
