INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dominos', 'Gameplay is a variation of the snake genre, in which players compete by surrounding each other with lines of dominos. Players change direction via a set of four directional buttons representing up, down, right, and left respectively. A player loses when they hit a wall, their own dominos, or their opponent''s, at which point all the dominos in their line "fall" down.' FROM games WHERE igdb_id = 18612 ON CONFLICT (game_id, language_code) DO NOTHING;
