INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Videocart-10: Maze, Cat and Mouse', 'Poor little mice, doomed to run around in a maze and escape as quickly as they can. As if that''s not enough, the owners of this maze pit you against a friend to see who will escape first. And then the diabolical owners take it one step further and add a cat to the maze mix - forcing you not only to escape first, but escape alive!
