INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shoot Away', 'Shoot Away is a 1977 electro-mechanical (EM) light gun shooter arcade game developed and published by Namco. Players use the rifle-shaped light guns to fire at clay pigeons, represented as flying white dots on a projector screen. There are two that must be shot down in each round, and players only get two bullets to hit them. Bonus points are awarded for shooting the pigeons as soon as they appear, or by destroying both of them with a single bullet. The game was a critical and commercial success, maintaining a presence in arcades into the 1980s.' FROM games WHERE igdb_id = 230598 ON CONFLICT (game_id, language_code) DO NOTHING;
