INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Basketball', 'A Basketball variant of pong exclusive to the Atari 2600 as games 45-46 of the launch title Video Olympics. The game features a simple game of one-on-one basketball playable by one or two players, one of the few early Atari 2600 to have a true single player feature with an AI-controlled opponent.' FROM games WHERE igdb_id = 287290 ON CONFLICT (game_id, language_code) DO NOTHING;
